use customer_behaviour;

SELECT * FROM customer_behaviour.customer;

-- customer_id', 'age', 'gender', 'item_purchased', 'category',
--        'purchase_amount', 'location', 'size', 'color', 'season',
--        'review_rating', 'subscription_status', 'shipping_type',
--        'discount_applied', 'previous_purchases', 'payment_method',
--        'frequency_of_purchases', 'age_group', 'purchase_frequency_days'],
--       dtype='object'
      
##Q1. What is the total revenue generated by male vs. female customers?
Select gender, sum(purchase_amount) as revenue from customer group by gender;

##Q2. Which customers used a discount but still spent more than the average purchase amount?
select avg(purchase_amount) from customer;
Select customer_id,purchase_amount from customer where discount_applied = "yes" and purchase_amount >= (select avg(purchase_amount) from customer);

##Q3. Which are the top 5 products with the highest average review rating?
Select item_purchased, round(Avg(review_rating),2) as Avg_Review_rating from customer group by item_purchased order by Avg_Review_rating desc limit 5;

##Q4. Compare the average Purchase Amounts between Standard and Express Shipping.
Select shipping_type, round(avg(purchase_amount),2) as Avr_Amount  from customer where shipping_type in ('Standard','Express') group by shipping_type limit 0,10000 ;

##Q5. Do subscribed customers spend more? Compare average spend and total revenue between subscribers and non-subscribers.
Select subscription_status,
Count(customer_id) as total_customers, round(Avg(purchase_amount),2) as AVR_Amount, 
round(Sum(Purchase_amount),2) as Total_revenue from customer group by subscription_status order by Total_revenue,AVR_Amount ;

##Q6. Which 5 products have the highest percentage of purchases with discounts applied?
select item_purchased, round(100 * Sum(case when discount_applied = 'yes' then 1 else 0 end) / count(*),2) as discount_rate 
from customer
group by item_purchased
order by discount_rate  desc
limit 5;

##Q7. Segment customers into New, Returning, and Loyal based on their total number of previous purchases, and show the count of each segment.

-- CTE (Common Table Expression)
with customer_type as (
select customer_id,previous_purchases,
Case 
	When previous_purchases = 1 then 'New'
    When previous_purchases  between 2 and 10 then 'Returning'
    else 'Loyal'
    End As customer_segment
From customer
)
Select customer_segment , Count(*) as 'Number_of_Customers'
from Customer_type
group by customer_segment;

##Q8. What are the top 3 most purchased products within each category?

with item_count as (
Select category, item_purchased, count(customer_id) as total_orders,
Row_number () over(partition by category order by count(customer_id) Desc) as item_rank 
From customer
group by category, item_purchased
)

select category, item_purchased, total_orders, item_rank from item_count where item_rank <= 3;

##Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?

Select subscription_status, count(customer_id) as Repeat_Customers from customer where previous_purchases >= 5 group by subscription_status;

##Q10. What is the revenue contribution of each age group?

select age_group, Sum(purchase_amount) as total_revenue from customer group by age_group order by total_revenue desc;
